// Custom Worker entry — wraps OpenNext's generated handler with a
// scheduled() handler for Cloudflare cron triggers.
//
// `.open-next/worker.js` is a build artifact (gitignored, regenerated by
// `opennextjs-cloudflare build` from `.next/`) — this file is the real,
// checked-in entrypoint. wrangler.jsonc's `main` points here, not at the
// generated file directly.
//
// @opennextjs/cloudflare exports no scheduled() handler of its own, so
// wrangler.jsonc's triggers.crons would otherwise fire into a no-op —
// confirmed via the identical finding on both Thoth's and Sopdet's own
// Cloudflare migrations. Each cron expression maps to exactly one
// /api/cron/* route, called the same bearer-token way Vercel Cron used to
// (see app/api/cron/*/route.ts's CRON_SECRET check).
import openNextHandler from "./.open-next/worker.js";

export * from "./.open-next/worker.js";

interface Env {
  CRON_SECRET?: string;
  SITE_URL?: string;
  // Self-referencing service binding (wrangler.jsonc's `services`) — calls
  // this same Worker's fetch handler directly, no edge/DNS hop. Required:
  // a Worker fetch()-ing its own public hostname via the global fetch()
  // gets rejected by Cloudflare as a loop (error 1042, "This request is
  // blocked") — same failure mode hit and fixed on both prior migrations.
  SELF?: { fetch(input: string, init?: RequestInit): Promise<Response> };
}

// Keep this map in sync with wrangler.jsonc's triggers.crons array — a cron
// expression with no entry here silently no-ops.
const CRON_ROUTES: Record<string, { path: string; method: "GET" | "POST" }> = {
  "0 2 * * *": { path: "/api/cron/sync-health", method: "GET" },
  "0 3 * * 1": { path: "/api/cron/sync-benchmarks", method: "GET" },
  "0 * * * *": { path: "/api/cron/sync-incidents", method: "GET" },
};

async function scheduled(
  event: { cron: string },
  env: Env,
  ctx: { waitUntil(promise: Promise<unknown>): void }
): Promise<void> {
  const route = CRON_ROUTES[event.cron];
  if (!route) {
    console.error(`scheduled(): no route mapped for cron expression "${event.cron}"`);
    return;
  }
  if (!env.CRON_SECRET) {
    console.error(`scheduled(): CRON_SECRET is not set — skipping dispatch to ${route.path}`);
    return;
  }
  if (!env.SELF) {
    console.error(
      `scheduled(): SELF service binding is not configured — skipping dispatch to ${route.path}`
    );
    return;
  }
  const base = (env.SITE_URL ?? "https://aichitect.dev").replace(/\/$/, "");
  const run = env.SELF.fetch(`${base}${route.path}`, {
    method: route.method,
    headers: { Authorization: `Bearer ${env.CRON_SECRET}` },
  }).then((res) => {
    if (!res.ok) console.error(`scheduled(): ${route.path} responded ${res.status}`);
  });
  ctx.waitUntil(run);
  await run;
}

export default { ...openNextHandler, scheduled };
